package me.pikanote.companion;
import android.app.*;import android.content.*;import android.os.*;import java.util.concurrent.*;
public final class PikaService extends Service{
 volatile boolean maintenance=false,voiceBusy=false;public static volatile PikaService instance;public volatile String status="Not connected";BleTransport ble;final ExecutorService deviceEvents=Executors.newSingleThreadExecutor();final ExecutorService sync=Executors.newSingleThreadExecutor();volatile boolean syncing=false;final ScheduledExecutorService voice=Executors.newSingleThreadScheduledExecutor();
 @Override public void onCreate(){super.onCreate();instance=this;NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("pika","Pika connection",NotificationManager.IMPORTANCE_LOW));startForeground(6,notification());ble=new BleTransport(this,this);try{PhoneVoice.recover(Store.get(this));PhoneAsk.recover(Store.get(this));}catch(Exception ignored){}voice.scheduleWithFixedDelay(this::processVoice,1,15,TimeUnit.SECONDS);voice.scheduleWithFixedDelay(this::refreshDeviceTelemetry,5,30,TimeUnit.SECONDS);}
 Notification notification(){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"pika").setSmallIcon(me.pikanote.companion.R.drawable.pika_notification).setContentTitle("Pika Companion").setContentText(status).setContentIntent(open).setOngoing(true).build();}
 void notifyStatus(){getSystemService(NotificationManager.class).notify(6,notification());}
 @Override public int onStartCommand(Intent intent,int flags,int id){ble.start("");notifyStatus();return START_STICKY;}
 void onConnected(){Store.get(this).connect(ble);scheduleSync();scheduleVoice();deviceEvents.execute(()->{try{if(Store.get(this).restoredPending())return;BleTransport.Reply reply=ble.rpc("/api/phone/settings-export","GET",null,null);if(reply.status==200){Store store=Store.get(this);synchronized(store){if(!store.restoredPending()){store.state.put("deviceSecrets",reply.json());store.save();}}}}catch(Exception e){ErrorJournal.add(this,"backup","settings-export",e.getMessage());}});}
 volatile boolean requested=false,fullRequested=false;
 void enqueueDeviceSync(long generation){deviceEvents.execute(()->scheduleDeviceSync(generation));}
 void enqueueBackgroundSync(){deviceEvents.execute(this::scheduleSync);}
 void scheduleDeviceSync(long generation){if(ble!=null&&!PhoneVoice.hasUploads(Store.get(this))&&Store.get(this).deviceAlreadySynced(ble.session,generation))return;scheduleSync();}
 void resumeDeferredSync(){deviceEvents.execute(()->{if(requested||Store.get(this).hasPending()||PhoneVoice.hasUploads(Store.get(this)))scheduleSync();});}
 String previewUnavailable(){if(maintenance||syncing||requested||voiceBusy||Store.get(this).previewInFlight.get())return "Synchronization or processing in progress — wait before testing";return ble==null?"Connect Pika to test":ble.previewUnavailable();}
 void scheduleSync(){scheduleSync(false);}
 synchronized void scheduleSync(boolean full){if(maintenance)return;requested=true;fullRequested|=full;if(syncing||ble==null||!ble.online||ble.deviceBusy||ble.preparingBulk)return;syncing=true;Store.get(this).syncProgress=.01f;final long session=ble.session;sync.execute(()->{try{for(;;){boolean all;synchronized(this){if(!requested||!ble.online||ble.session!=session)break;requested=false;all=fullRequested;fullRequested=false;}Store.get(this).synchronize(ble,all);PhoneAsk.importFeed(Store.get(this));scheduleVoice();if(PhoneVoice.uploadPending(Store.get(this),ble)){synchronized(this){requested=true;}}if(ble.online&&ble.session==session){status="Pika connected";notifyStatus();}}}catch(Exception e){if(!(e instanceof Store.SyncDeferredException))ErrorJournal.add(this,"sync","exchange",e.getClass().getSimpleName()+": "+e.getMessage());Throwable cause=e;while(cause.getCause()!=null)cause=cause.getCause();String message=cause instanceof java.util.concurrent.TimeoutException?"Pika did not answer; tap reconnect to retry":cause.getMessage();if(cause instanceof Store.SyncDeferredException){requested=true;}else if(ble.online&&ble.session==session){Store.get(this).syncMessage=message==null?"Transfer interrupted; partial file kept":message;notifyStatus();}}finally{synchronized(this){syncing=false;if(requested&&ble.online&&!ble.deviceBusy)new Handler(Looper.getMainLooper()).post(this::scheduleSync);}}});}
 void scheduleVoice(){voice.execute(this::processVoice);}
 void refreshDeviceTelemetry(){try{BleTransport b=ble;if(b==null||!b.online||syncing||b.deviceBusy||b.preparingBulk)return;long session=b.session;org.json.JSONObject status=b.rpc("/api/manager/state","GET",null,null).json();org.json.JSONObject device=status.optJSONObject("device");if(device!=null&&b.online&&session==b.session)Store.get(this).acceptDeviceTelemetry(device,b.address);}catch(Exception ignored){}}
 void processVoice(){synchronized(this){if(maintenance||voiceBusy)return;voiceBusy=true;}PhoneAsk.kick();try{OfflineInbox.discover(Store.get(this));PhoneVoice.process(Store.get(this),ble);OfflineInbox.process(Store.get(this));if(ble!=null&&ble.online&&PhoneVoice.hasUploads(Store.get(this)))scheduleSync();}catch(Exception ignored){}finally{voiceBusy=false;}}
 @Override public void onDestroy(){deviceEvents.shutdownNow();voice.shutdownNow();sync.shutdownNow();if(ble!=null)ble.close();instance=null;super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
